    # Initialize a set to keep track of visited nodes
recurse_set = set()

    while stack:
        (node, path) = stack.pop()
        # Mark this node as visited
        if node not in recurse_set:
            recurse_set.add(node)
            # Check if we reached the goal
            if node == goal:
                return path
            # Explore all neighbors
            for neighbor in graph[node]:
                if neighbor not in recurse_set:
                    new_path = path + [neighbor]
                    stack.append((neighbor, new_path))
    # If we have exhausted all paths and haven't found the goal, return None
    return None

