def find_path(graph, start, goal):
    visited = {}
    stack = [(start, [start])]
    while stack:
        vertex, path = stack.pop()
        if vertex not in visited:
            visited[vertex] = path
            if vertex == goal:
                return path
            for neighbour in graph[vertex]:
                if neighbour not in visited:
                    stack.append((neighbour, path + [neighbour]))
    return None
